const M=CRMModel,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('ru-RU').format(+n||0)+' ₽';
const KEY='activprofi-server-cache',PROTOTYPE_KEY='activprofi-variant-b-v2';
let state=null,userId='',page=location.hash==='#funnel'?'funnel':'overview',projectId='1',projectTab='dashboard',selected='1',pipeId='inbound',search='',filterStage='',taskProject='',taskStatus='',reportProject='',reportFrom='',reportTo='',docTask='',chosenDoc='',chat=null,zoom=1;
const u=()=>state.users.find(x=>x.id===userId)||state.users[0],name=id=>state.users.find(x=>x.id===id)?.name||'Не назначен',P=()=>M.project(state,projectId),vp=()=>M.visibleProjects(state,u()),vt=()=>M.visibleTasks(state,u()),vc=()=>M.visibleClients(state,u());
function showLogin(message){const screen=$('#login-screen');if(screen)screen.hidden=false;const loginForm=$('#login-form');if(loginForm)loginForm.hidden=false;const passwordForm=$('#password-form');if(passwordForm)passwordForm.hidden=true;$('#sidebar').hidden=true;document.querySelector('.workspace').hidden=true;const error=$('#login-error');if(!error)return;if(message){error.hidden=false;error.textContent=message}else error.hidden=true}
function showPasswordGate(){const screen=$('#login-screen');if(screen)screen.hidden=false;$('#sidebar').hidden=true;document.querySelector('.workspace').hidden=true;const loginForm=$('#login-form');if(loginForm)loginForm.hidden=true;const form=$('#password-form');if(form)form.hidden=false;const error=$('#password-error');if(error)error.hidden=true}
function showApp(){$('#login-screen').hidden=true;$('#sidebar').hidden=false;document.querySelector('.workspace').hidden=false}
function adoptWorkspace(data){state=data.state;state.revision=data.revision;if(data.user?.id)userId=data.user.id;LeadModel.upgrade(state);Communications.upgrade(state);CRMInbox.upgrade(state);DeliveryModel.upgrade(state);snapshotRecords()}
function snapshotRecords(){if(!state)return;const pack=list=>new Map((list||[]).map(item=>[item.id,JSON.stringify(item)]));window.crmBaseline={clients:pack(state.clients),projects:pack(state.projects),tasks:pack(state.tasks),rest:JSON.stringify({users:state.users,pipelines:state.pipelines,leadBatches:state.leadBatches,materials:state.materials,messages:state.messages,outbox:state.outbox,communications:state.communications,voiceCampaigns:state.voiceCampaigns,conversations:state.conversations,externalMessages:state.externalMessages,rolePermissions:state.rolePermissions,desk:state.desk,googleClientId:state.googleClientId})}}
function recordChanges(){const base=window.crmBaseline;if(!base)return null;const changes=[];for(const [key,kind] of [['clients','client'],['projects','project'],['tasks','task']]){for(const item of state[key]||[]){const prev=base[key].get(item.id);const now=JSON.stringify(item);if(prev!==now)changes.push({kind,id:item.id,rev:Number(item.recordRev)||0,data:item})}}const rest=JSON.stringify({users:state.users,pipelines:state.pipelines,leadBatches:state.leadBatches,materials:state.materials,messages:state.messages,outbox:state.outbox,communications:state.communications,voiceCampaigns:state.voiceCampaigns,conversations:state.conversations,externalMessages:state.externalMessages,rolePermissions:state.rolePermissions,desk:state.desk,googleClientId:state.googleClientId});return {changes,other:rest!==base.rest}}
function persist(){try{SheetsModel.reconcile(state);const plan=recordChanges();const granular=plan&&plan.changes.length&&!plan.other;const xhr=new XMLHttpRequest();xhr.open(granular?'POST':'PUT',granular?'/api/records':'/api/workspace',false);xhr.setRequestHeader('Content-Type','application/json');xhr.setRequestHeader('X-Requested-With','ActivProfi');xhr.send(JSON.stringify(granular?{items:plan.changes}:{revision:state.revision,state}));if(xhr.status>=200&&xhr.status<300){adoptWorkspace(JSON.parse(xhr.responseText));boardRecord();queueMicrotask(()=>sheetsFlush());return true}let message='Не удалось сохранить';try{message=JSON.parse(xhr.responseText).error||message}catch{}if(xhr.status===401){showLogin('Сессия закончилась. Войдите снова.');return false}showFormError(message);return false}catch{toast('Нет связи с сервером.');return false}}
async function serverCommand(url,body){const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'ActivProfi'},body:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Не удалось сохранить на сервере');adoptWorkspace(data);return data}
async function login(fd){const response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'ActivProfi'},body:JSON.stringify({login:String(fd.get('login')||'').trim(),password:fd.get('password')||''})});const data=await response.json().catch(()=>({}));if(!response.ok){showLogin(data.error||'Неверный логин или пароль');return}await boot(true)}
async function logout(){await fetch('/api/auth/logout',{method:'POST',headers:{'X-Requested-With':'ActivProfi'}});state=null;userId='';chat=null;page='overview';showLogin('')}
async function boot(){try{const me=await fetch('/api/auth/me');if(!me.ok){showLogin('');return}const meData=await me.json().catch(()=>({}));if(meData.user?.mustChangePassword){showPasswordGate();return}const ws=await fetch('/api/workspace');const data=await ws.json();if(!ws.ok){showLogin(data.error||'Не удалось загрузить данные');return}adoptWorkspace(data);const saved=sessionStorage.getItem('crm-pipeline');pipeId=saved&&state.pipelines.some(p=>p.id===saved)?saved:(state.pipelines.find(p=>p.stages.some(t=>t.systemKey==='cold'))?.id||state.pipelines[0]?.id||'');const first=vp()[0];if(first&&!vp().some(p=>p.id===projectId))projectId=first.id;showApp();render();if(typeof telegramTick==='function')telegramTick().catch(()=>{});if(typeof loadMailStatus==='function')loadMailStatus().then(()=>{if(state)render()}).catch(()=>{});if(typeof loadSipuni==='function')loadSipuni().then(changed=>{if(changed&&state)render()}).catch(()=>{});if(typeof loadKp==='function')loadKp().then(()=>{if(state)render()}).catch(()=>{});if(typeof loadPitch==='function')loadPitch().catch(()=>{})}catch{showLogin('Нет связи с сервером. Проверьте, что CRM запущена.')}}
function migrationBanner(){if(!state||u().role!=='admin')return '';let local=false;try{local=!!localStorage.getItem(PROTOTYPE_KEY)||!!localStorage.getItem('activprofi-variant-b-v1')}catch{}return `<section class="panel migration-banner"><div class="panel-head"><h2>Данные сервера</h2></div><p class="hint">Общая база хранится на сервере. Можно скачать JSON или один раз перенести выгрузку из браузерного прототипа.</p><div class="actions">${action('Скачать JSON','migration-export')}<button class="btn" type="button" data-action="migration-pick">Загрузить JSON</button><input id="migration-file" type="file" accept="application/json,.json" hidden>${local?action('Перенести данные этого браузера','migration-local'):''}</div></section>`}
async function exportServerJson(){const response=await fetch('/api/migration/export');const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Не удалось скачать');download('activprofi-crm.json',new Blob([JSON.stringify(data)],{type:'application/json'}))}
async function readPrototypeFiles(){const map=new Map();try{const db=await new Promise((ok,no)=>{const request=indexedDB.open('activprofi-board-files');request.onerror=()=>no(request.error);request.onsuccess=()=>ok(request.result)});if(!db.objectStoreNames.contains('files')){db.close();return map}const rows=await new Promise((ok,no)=>{const tx=db.transaction('files');const store=tx.objectStore('files');const valuesRequest=store.getAll();const keysRequest=store.getAllKeys();let values,ids;const done=()=>{if(values&&ids)ok(ids.map((id,i)=>[id,values[i]]))};valuesRequest.onsuccess=()=>{values=valuesRequest.result;done()};keysRequest.onsuccess=()=>{ids=keysRequest.result;done()};tx.onerror=()=>no(tx.error)});for(const [id,value] of rows)if(value)map.set(String(id),value);db.close()}catch{}return map}
async function uploadPrototypeFiles(dump,files){const source=dump.state||dump;for(const project of source.projects||[]){for(const asset of project.board?.assets||[]){const id=String(asset.fileId||asset.id||'');const file=files.get(id);if(!file)continue;const response=await fetch('/api/files/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(asset.name||'file'),'X-Project-Id':project.id,'X-Requested-With':'ActivProfi'},body:file});if(!response.ok)throw Error('Не удалось перенести файл '+(asset.name||id))}}}
async function importDump(payload,files){const data=await serverCommand('/api/migration/import',payload);if(files)await uploadPrototypeFiles(payload,files);render();const passwords=data.temporaryPasswords||[];if(passwords.length)modal('Временные пароли',`<p class="hint">Пароли показаны один раз. Передайте их сотрудникам. Не сохраняйте этот список в общем файле.</p>${passwords.map(item=>`<p><strong>${esc(item.name)}</strong><br>Логин: ${esc(item.login)}<br>Пароль: ${esc(item.password)}</p>`).join('')}`,'',()=>'saved');else toast('Данные загружены на сервер')}
async function importLocalPrototype(){let raw=null;try{raw=localStorage.getItem(PROTOTYPE_KEY)||localStorage.getItem('activprofi-variant-b-v1')}catch{}if(!raw)throw Error('В этом браузере нет данных прототипа');const payload=JSON.parse(raw);await importDump(payload,await readPrototypeFiles())}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function fmt(v){if(!v)return 'Не задан';return new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}
function badge(s,t=''){return `<span class="chip ${t}">${esc(s)}</span>`}
function action(label,a,id='',primary=false){try{accessAction(a)}catch{return ''}return `<button class="btn ${primary?'primary':''}" data-action="${a}" data-id="${esc(id)}">${label}</button>`}
function link(label,a,id=''){return `<button class="link" data-action="${a}" data-id="${esc(id)}">${label}</button>`}
function heading(title,sub='',buttons=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${buttons}</div></div>`}
function empty(t){return `<div class="empty">${esc(t)}</div>`}
function option(value,label,selectedValue){return `<option value="${esc(value)}" ${String(value)===String(selectedValue)?'selected':''}>${esc(label)}</option>`}
function field(label,key,value='',type='text',required=false){return `<label class="field">${label}<input name="${key}" value="${esc(value)}" type="${type}" ${required?'required':''} ${type==='number'?'min="0" step="0.5"':''}></label>`}
function selectField(label,key,options){return `<label class="field">${label}<select name="${key}">${options}</select></label>`}
function area(label,key,value=''){return `<label class="field">${label}<textarea name="${key}">${esc(value)}</textarea></label>`}
function draftStore(){try{return localStorage}catch{return null}}
function readDraftForm(form){const values={},boxes={};if(!form)return values;for(const el of form.elements){if(!el.name||el.type==='password'||el.type==='file'||CRMDraft.isSecret(el.name)||el.name.startsWith('staff'))continue;if(el.type==='checkbox'){(boxes[el.name]||=[]);if(el.checked)boxes[el.name].push(el.value)}else if(el.type==='radio'){if(el.checked)values[el.name]=el.value}else values[el.name]=el.value}return CRMDraft.scrubDraft({...values,...boxes})}
function writeDraftForm(form,values){if(!form||!values)return;for(const el of form.elements){if(!el.name||!(el.name in values)||el.type==='file'||el.type==='password')continue;if(el.type==='checkbox'){const list=Array.isArray(values[el.name])?values[el.name]:[values[el.name]];el.checked=list.map(String).includes(String(el.value))}else if(el.type==='radio')el.checked=String(el.value)===String(values[el.name]);else el.value=values[el.name]}}
function saveModalDraft(form){if(!form?.dataset.draftId||form.dataset.draftDone)return;CRMDraft.rememberDraft(draftStore(),u().id,form.dataset.draftId,readDraftForm(form))}
function bindModalDraft(form){if(!form?.dataset.draftId)return;const saved=CRMDraft.readDraft(draftStore(),u().id,form.dataset.draftId);if(saved)writeDraftForm(form,saved.values);if(form.dataset.draftBound)return;form.dataset.draftBound='1';if(saved){const note=document.createElement('p');note.className='hint draft-note';note.innerHTML='Черновик восстановлен. Он хранится в этом браузере, пароль в него не записывается. <button type="button" class="link" data-action="clear-draft">Очистить черновик</button>';const actions=form.querySelector('.dialog-actions');form.insertBefore(note,actions)}const keep=()=>saveModalDraft(form);form.addEventListener('input',keep);form.addEventListener('change',keep)}
function projectDraftId(id){return id?'project:'+id:'project:new'}
function projectReturnKey(){return 'activprofi-draft-return:'+(u()?.id||'')}
function projectReturnId(){try{const raw=localStorage.getItem(projectReturnKey());if(!raw||!raw.startsWith('project:'))return null;return raw==='project:new'?'':raw.slice(8)}catch{return null}}
function markProjectReturn(draftId){try{localStorage.setItem(projectReturnKey(),draftId)}catch{}}
function clearProjectReturn(){try{localStorage.removeItem(projectReturnKey())}catch{}}
function projectReturnBanner(){const id=projectReturnId();if(id===null)return '';const draft=CRMDraft.readDraft(draftStore(),u().id,projectDraftId(id));if(!draft)return '';return `<p class="hint">Форма проекта сохранена в этом браузере. <button type="button" class="link" data-action="return-project-form">Вернуться к форме</button></p>`}
function modal(title,body,label,onSave,draftId=''){let d=$('#modal');d.classList.remove('annotation-modal');d.innerHTML=`<form id="modal-form"${draftId?` data-draft-id="${esc(draftId)}"`:''}><h2>${esc(title)}</h2><p class="form-error" id="modal-error" hidden></p>${body}<div class="dialog-actions"><button type="button" class="btn" data-action="close-modal">Закрыть</button>${label?`<button class="btn primary" type="submit">${label}</button>`:''}</div></form>`;if(!d.open)d.showModal();const form=$('#modal-form');if(draftId)bindModalDraft(form);form.onsubmit=async e=>{e.preventDefault();let submit=e.submitter;try{if(submit)submit.disabled=true;const result=await onSave(new FormData(e.target));if(result===false)return;if(result!=='saved'&&!persist())return;if(draftId){form.dataset.draftDone='1';CRMDraft.forgetDraft(draftStore(),u().id,draftId);if(String(draftId).startsWith('project:'))clearProjectReturn()}d.close();render()}catch(err){showFormError(err.message)}finally{if(submit)submit.disabled=false}}}
function showFormError(message){const error=$('#modal-error'),dialog=$('#modal');if(!error||!dialog?.open){toast(message);return}const phone=document.querySelector('#modal-form [name=phone]')?.value||'';const digits=typeof LeadModel!=='undefined'&&LeadModel.phone?LeadModel.phone(phone):String(phone).replace(/\D/g,'');const existing=/уже есть в базе/.test(message)?(state.clients||[]).find(item=>M.canClient(state,u(),item)&&digits&&LeadModel.phone(item.phone)===digits):null;error.hidden=false;error.innerHTML=esc(message)+(existing?` <button type="button" class="link" data-action="open-duplicate-client" data-id="${esc(existing.id)}">Открыть карточку «${esc(existing.name)}»</button>`:'');dialog.scrollTop=0;error.scrollIntoView({block:'center'})}
function go(p){if(!accessPage(p))return toast('Раздел недоступен по вашим правам');page=p;render();window.scrollTo(0,0)}
function openProject(id,tab='dashboard'){if(!M.canProject(state,u(),id))return toast('Проект недоступен этой роли');projectId=id;projectTab=tab;docTask='';go('project')}
function openRoad(id){if(!M.canProject(state,u(),id))return toast('Дорожная карта недоступна');projectId=id;go('project-roadmap')}
const nav=[['overview','Обзор','home'],['guide','Как работать','check'],['clients','Клиенты','users'],['inbox','Клиенты: переписка','users'],['telegram','Чат команды','users'],['funnel','Воронки','board'],['leads','Базы лидов','users'],['projects','Проекты','folder'],['delivery','Разработка','board'],['tasks','Задачи','check'],['roadmap','Дорожные карты','clock'],['reports','Отчёты','chart'],['team','Команда и роли','users']];
function render(){if(!state)return;if(!accessPage(page))page='overview';const active=page==='project'?'projects':page==='project-roadmap'?'roadmap':page;$('#sidebar').innerHTML=`<div class="brand"><img src="assets/studio-logo.png" alt="АктивПрофи"><div>АктивПрофи<small>CRM КОМАНДЫ</small></div></div><div class="agency">${esc(name(u().id))}<small>${M.roles[u().role]}</small></div><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div>${nav.filter(([k])=>accessPage(k)).map(([k,l,i])=>{const label=k==='team'&&u().role!=='admin'?'Команда':l;return `<button class="nav ${k===active?'active':''}" data-go="${k}" title="${label}" aria-label="${label}">${icon(i)}<span>${label}</span>${k==='inbox'&&inboxCount()?`<b class="inbox-count">${inboxCount()}</b>`:''}${k==='telegram'&&telegramUnread?`<b class="tg-count">${telegramUnread}</b>`:''}</button>`}).join('')}<div class="side-bottom"><strong>АктивПрофи</strong>Данные хранятся на сервере.<br><span>Общая база команды.</span></div>`;$('#role-bar').innerHTML=`<span class="agency-inline">${esc(name(u().id))} · ${esc(M.roles[u().role])}</span><button class="btn" type="button" data-action="change-password">Сменить пароль</button><button class="btn" type="button" data-action="logout">Выйти</button>`;$('#crumb').textContent=active==='team'&&u().role!=='admin'?'Команда':(nav.find(x=>x[0]===active)?.[1]||'Проект');$('#app').innerHTML=({overview,guide:guideView,clients,inbox:inboxView,telegram:telegramView,funnel,leads:leadsView,projects,delivery:deliveryBoard,project:projectView,tasks,roadmap,'project-roadmap':roadView,reports,team:teamAccess}[page]||overview)();renderChat();hydrateBoardImages();if(page==='project'&&projectTab==='telegram')fillProjectTelegram().catch(err=>toast(err.message))}
function projectCards(){const list=vp();if(!list.length)return empty((u().role==='sales'||u().role==='sales_intern')?'Проектов пока нет. Они появляются, когда клиент соглашается и вы передаёте сделку в разработку.':'Проектов в вашей зоне пока нет');return `<div class="project-grid">${list.map(p=>`<button class="project-card" data-action="project" data-id="${p.id}">${preview(p)}<div class="project-body">${badge(p.status)}${typeof telegramProjectCount==='function'&&telegramProjectCount(p.id)?`<b class="tg-count">${telegramProjectCount(p.id)}</b>`:''}<h3>${esc(p.title)}</h3><p>${esc(p.client)} · ${esc(name(p.leaderId))}</p><div class="progress"><span style="width:${M.progress(state,u(),p.id)}%"></span></div><div class="project-meta"><span>Выполнено ${M.progress(state,u(),p.id)}%${!M.has(state,u(),'tasks.all')?' ваших задач':''}</span><span>До ${fmt(p.due)} ↗</span></div></div></button>`).join('')}</div>`}
function deskSettings(){if(u().role!=='admin')throw Error('Назначения меняет администратор');const desk=state.desk||{};const people=state.users.filter(person=>person.active!==false);const opts=(selected,roles)=>option('','— не выбран —',selected)+people.filter(person=>roles.includes(person.role)).map(person=>option(person.id,person.name+' · '+M.roles[person.role],selected)).join('');modal('Назначения по умолчанию',selectField('Дежурный по неизвестным номерам','dutyUserId',opts(desk.dutyUserId,['sales','rop','admin']))+selectField('Руководитель новых проектов','defaultLeaderId',opts(desk.defaultLeaderId,['leader','admin','dev_head']))+selectField('Проджект новых проектов','defaultPmId',opts(desk.defaultPmId,['pm','admin','dev_head']))+'<p class="hint">Неизвестный номер видит дежурный, руководитель отдела и администратор. Новичок его не видит. Если дежурный не выбран, номера идут по очереди. Новые проекты получают руководителя и проджекта из этих полей.</p>','Сохранить',fd=>{state.desk={dutyUserId:fd.get('dutyUserId')||'',defaultLeaderId:fd.get('defaultLeaderId')||'',defaultPmId:fd.get('defaultPmId')||''};toast('Назначения сохранены')})}
function auditBanners(){let html='';if(['admin','rop'].includes(u().role)){const waiting=(state.clients||[]).filter(client=>client.awaitingManager&&!client.ownerId);if(waiting.length)html+=`<section class="panel" id="waiting-managers"><div class="panel-head"><h2>Ждут менеджера</h2></div>${waiting.map(client=>`<button class="client-row" data-action="client" data-id="${esc(client.id)}"><div><strong>${esc(client.name)}</strong><p>${esc(client.company||client.phone||'Менеджер не назначен')}</p></div></button>`).join('')}</section>`}if(['admin','leader','pm','dev_head'].includes(u().role)){const bare=(state.projects||[]).filter(project=>!project.leaderId||!project.pmId);const mine=bare.filter(project=>u().role==='admin'||u().role==='dev_head'||(u().role==='leader'&&!project.leaderId)||(u().role==='pm'&&!project.pmId));if(mine.length)html+=`<section class="panel" id="bare-projects"><div class="panel-head"><h2>Новые проекты без команды</h2></div>${mine.map(project=>`<button class="client-row" data-action="project" data-id="${esc(project.id)}"><div><strong>${esc(project.title)}</strong><p>Срок ${esc(project.due||'не задан')}</p></div></button>`).join('')}</section>`}return html}
function overview(){if(typeof sellerHome==='function'&&(u().role==='sales'||u().role==='sales_intern'))return sellerHome();const r=M.report(state,u()),risk=r.risk;return auditBanners()+(typeof sipuniBanner==='function'?sipuniBanner():'')+migrationBanner()+heading('Ваш рабочий день','Проекты, задачи и ближайшие действия',action('Новая задача','new-task','',true))+`<div class="stats">${[['Доступные проекты',r.projects.length],['Задачи в работе',risk.working.length],['Просрочено',risk.overdue.length],['Критические сроки',risk.critical.length]].map(([l,v])=>`<button class="stat" data-go="reports"><div class="stat-label">${l}</div><strong>${v}</strong><small>По вашей области ответственности</small></button>`).join('')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>Ближайшие задачи</h2>${link('Все задачи →','go-tasks')}</div>${taskRows(vt().filter(t=>t.status!=='Готово').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3))}</section><section class="panel"><div class="panel-head"><h2>Что требует внимания</h2></div><div class="detail"><p><strong>${risk.overdue.length}</strong> задач с прошедшим сроком.</p><p><strong>${risk.critical.length}</strong> задач: срок до трёх дней, осталось не менее восьми часов работы.</p>${action('Посмотреть отчёт','go-reports')}${M.has(state,u(),'sales.analytics')?`<p>Сумма доступных сделок: <strong>${money(r.total)}</strong></p>`:''}</div></section></div><div class="section-title"><h2>Проекты в работе</h2>${link('Все проекты ↗','go-projects')}</div>${projectCards()}`}
function funnel(){let pipe=state.pipelines.find(x=>x.id===pipeId)||state.pipelines[0];pipeId=pipe.id;const all=vc().filter(c=>!c.inLeadBase&&c.pipelineId===pipe.id);return heading('Воронки','Этапы слева направо. Карточки клиентов — под текущим этапом.',(M.has(state,u(),'pipelines.manage')?action('+ Этап воронки','add-stage','',true)+action('+ Воронка','add-pipeline'):'')+(M.has(state,u(),'clients.edit')?action('+ Клиент','new-client'):'') )+funnelLeadTools()+(all.length?'':'<p class="hint">Ваших сделок в этой воронке пока нет. Руководитель передаст лид, либо добавьте клиента кнопкой выше.</p>')+(M.has(state,u(),'voice.manage')?`<div class="actions" style="margin-bottom:16px">${action('Подготовить обзвон (звонки пока не идут)','voice-campaign')}</div>`:'')+`<div class="toolbar"><select id="pipeline" aria-label="Воронка">${state.pipelines.map(p=>option(p.id,p.name,pipe.id)).join('')}</select><span class="muted">${all.length} клиентов · ${money(all.reduce((a,c)=>a+c.amount,0))}</span></div><p class="funnel-hint">Перетащите карточку в другой этап. Стрелки листают этапы, которые не поместились на экран.</p><div class="funnel-scroll"><button type="button" class="funnel-arrow" data-funnel-scroll="-1" aria-label="Предыдущие этапы">←</button><div class="funnel-board" id="funnel-board">${pipe.stages.map((s,i)=>{const cs=all.filter(c=>c.stageId===s.id);return `<section class="stage-column" data-drop-stage="${s.id}"><div class="stage-head"><h3>${esc(s.name)} <span>${cs.length}</span></h3>${M.has(state,u(),'pipelines.manage')?`<div class="stage-controls">${link('Название','rename-stage',s.id)}${i?link('←','stage-left',s.id):''}${i<pipe.stages.length-1?link('→','stage-right',s.id):''}</div>`:''}<small>${money(cs.reduce((a,c)=>a+c.amount,0))} · ${s.kind==='won'?'Успех':s.kind==='lost'?'Отказ':'В работе'}</small></div>${cs.map(c=>`<div class="deal-wrap"><button class="deal" draggable="true" data-drag-client="${c.id}" data-action="client" data-id="${c.id}">${badge(c.source)}<strong>${esc(c.name)}</strong><p>${esc(c.company)}</p>${c.sourceComment?`<small class="deal-comment">${esc(c.sourceComment)}</small>`:''}<b>${money(c.amount)}</b><small>${esc(c.next)}<br>${fmt(c.when)} · ${esc(name(c.ownerId))}</small></button>${c.phone&&M.canClient(state,u(),c)?`<button type="button" class="btn sipuni-deal" data-action="sipuni-call" data-id="${esc(c.id)}">Позвонить</button>`:''}</div>`).join('')}${!cs.length?'<p class="drop-hint">Переместите клиента сюда</p>':''}</section>`}).join('')}<button class="stage-add" data-action="add-stage" ${!M.has(state,u(),'pipelines.manage')?'hidden':''}>+ Добавить этап</button></div><button type="button" class="funnel-arrow" data-funnel-scroll="1" aria-label="Следующие этапы">→</button></div>`}
function clients(){const phoneBanner=typeof sipuniBanner==='function'?sipuniBanner():'';let rows=vc().filter(c=>[c.name,c.company,c.phone,c.email,c.socials].join(' ').toLowerCase().includes(search.toLowerCase())&&(!mailingLoss||c.lossReason===mailingLoss));if(!rows.some(c=>c.id===selected))selected=rows[0]?.id;let c=rows.find(c=>c.id===selected);return phoneBanner+heading('Клиенты','Список, следующий контакт и история рядом', M.has(state,u(),'clients.edit')?action('Добавить клиента','new-client','',true)+(LeadModel.canImport(u(),state)?action('Загрузить базу','import-leads'):''):'')+(typeof mailingToolbar==='function'?mailingToolbar():'')+`<div class="toolbar"><input id="client-search" aria-label="Поиск клиентов" value="${esc(search)}" placeholder="Имя, компания или телефон"><span>${rows.length} клиентов</span></div><div class="client-layout"><section class="panel client-list">${rows.map(x=>`<button class="client-row ${x.id===selected?'active':''}" data-action="client" data-id="${x.id}"><div><strong>${esc(x.name)}</strong><p>${esc(x.company)}</p><small>${fmt(x.when)} · ${esc(name(x.ownerId))}</small></div>${badge(M.stage(state,x)?.name||(x.inLeadBase?'Общая база':'Без этапа'))}</button>`).join('')||(search?empty('Никого не нашли. Проверьте имя или телефон.'):empty((u().role==='sales'||u().role==='sales_intern')?'Пока нет ваших клиентов. Их передаст руководитель, либо нажмите «Добавить клиента».':'Клиенты не найдены'))}</section><section class="panel">${c?`<div class="detail"><div class="detail-title"><div><h2>${esc(c.name)}</h2><p>${esc(c.company)}</p></div></div><div class="actions">${action('Следующий контакт','contact',c.id,true)}${typeof silenceButton==='function'?silenceButton(c):''}${action('Изменить','edit-client',c.id)}${LeadModel.canImport(u(),state)?action('Передать менеджеру','handover-lead',c.id,true):''}</div><div class="detail-grid"><div><small>Телефон</small>${esc(c.phone)||'Не указан'}${typeof sipuniCallButton==='function'?sipuniCallButton(c):''}</div><div><small>Почта</small>${esc(c.email||'Не указана')}</div><div class="social-contact"><small>Соцсети и мессенджеры</small>${socialContactLinks(c)}</div><div><small>Сумма сделки</small>${money(c.amount)}</div><div><small>Менеджер</small>${esc(name(c.ownerId))}</div><div><small>База лидов</small>${esc(state.leadBatches.find(b=>b.id===c.batchId)?.name||'Вручную')}</div><div><small>Источник</small>${esc(c.source)}</div></div>${dealCard(c)}${typeof kpSection==='function'?kpSection(c):''}${typeof pitchSection==='function'?pitchSection(c):''}${typeof paySection==='function'?paySection(c):''}${typeof projectHandover==='function'?projectHandover(c):''}${(c.batchId||c.sourceComment)?`<div class="source-comment"><small>Комментарий из базы</small><p>${esc(c.sourceComment||'В исходном файле комментария не было')}</p></div>`:''}<label class="field">Этап воронки<select id="client-stage">${c.inLeadBase?'<option value="" selected disabled>Общая база — выберите этап для переноса в воронку</option>':''}${state.pipelines.find(p=>p.id===c.pipelineId).stages.map(s=>option(s.id,s.name,c.stageId)).join('')}</select></label><div class="next-action"><strong>${esc(c.next||'Назначьте следующий шаг')}</strong><small>${fmt(c.when)}</small></div>${c.project&&M.canProject(state,u(),c.project)?action('Связанный проект →','project',c.project):''}${inboxCards('client',c.id)}${communicationPanel('client',c.id)}${clientTimeline(c)}<form id="client-note" class="note-form"><input name="note" aria-label="Заметка клиента" required placeholder="Итог разговора…"><button class="btn">Добавить</button></form></div>`:empty('Выберите клиента')}</section></div>`}
function projects(){const unfinished=CRMDraft.readDraft(draftStore(),u().id,'project:new');return heading('Проекты','Превью, сроки и рабочее пространство каждого проекта',M.has(state,u(),'projects.create')?action('+ Проект','new-project','',true):'')+(unfinished?'<p class="hint">Есть незавершённый проект. <button type="button" class="link" data-action="return-project-form">Открыть черновик</button></p>':'')+projectCards()}
const ptabs=[['dashboard','Дашборд'],['board','Онлайн-доска'],['materials','Материалы'],['tasks','Задачи'],['discussions','Обсуждения'],['telegram','Группа Telegram'],['about','О проекте']];
function projectView(){const p=P();if(!p||!M.canProject(state,u(),p.id))return empty('Проект недоступен');return heading(p.title,p.client+' · Руководитель: '+name(p.leaderId),action('Все проекты','go-projects')+action('Роад мэп →','road',p.id))+inboxCards('project',p.id)+communicationPanel('project',p.id)+`<div class="tabs project-tabs">${ptabs.map(([k,l])=>`<button class="tab ${projectTab===k?'active':''}" data-action="project-tab" data-id="${k}">${l}${k==='telegram'&&typeof telegramProjectCount==='function'&&telegramProjectCount(p.id)?`<b class="tg-count">${telegramProjectCount(p.id)}</b>`:''}</button>`).join('')}</div><div class="project-content">${({dashboard:projectDashboard,board:boardView,materials:materialsView,tasks:projectTasks,discussions:discussionView,telegram:projectTelegram,about:aboutView}[projectTab])()}</div>`}
function projectDashboard(){let p=P(),r=M.risk(vt().filter(t=>t.projectId===p.id));return `<div class="project-detail-grid"><div><section class="panel big-preview">${p.mockup?.data?`<img class="mockup-image" src="${p.mockup.data}" alt="Макет проекта ${esc(p.title)}">`:preview(p)}<div class="panel-head"><h2>Макет проекта</h2>${action('Загрузить макет','upload-mockup')}</div><p class="report-note">${p.mockup?.data?esc(p.mockup.name):'Иллюстративный эскиз. Можно загрузить собственный PNG или JPG.'}</p></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Задачи проекта</h2>${link('+ Добавить','new-task',p.id)}</div>${taskRows(vt().filter(t=>t.projectId===p.id).slice(0,4))}</section></div><div><section class="panel"><div class="panel-head"><h2>Коротко о проекте</h2></div><div class="detail-list"><p><span>Срок</span><strong>${fmt(p.due)}</strong></p><p><span>Готово задач</span><strong>${M.progress(state,u(),p.id)}%</strong></p><p><span>Просрочено</span><strong>${r.overdue.length}</strong></p><p><span>Критично</span><strong>${r.critical.length}</strong></p><p>${esc(p.description)}</p></div></section><div class="actions">${action('Онлайн-доска','project-tab','board')}${action('Материалы','project-tab','materials')}${action('Роад мэп','road',p.id)}</div></div></div>`}
function projectTasks(){return `<div class="panel"><div class="panel-head"><h2>Задачи проекта</h2>${action('+ Добавить задачу','new-task',projectId,true)}</div>${taskRows(vt().filter(t=>t.projectId===projectId))}</div>`}
function taskRows(ts){if(!ts.length)return empty('Задач в этой области ответственности пока нет');return ts.map(t=>`<div class="task-row rich-task"><div class="copy"><button class="task-title" data-action="task" data-id="${t.id}">${esc(t.title)}</button><small>${esc(M.project(state,t.projectId)?.title)} · ${esc(name(t.assigneeId))}</small><div class="task-meta">${badge(t.status)} <span class="${t.status!=='Готово'&&t.due<M.today()?'overdue':''}">До ${fmt(t.due)}</span><span>Осталось ${t.remaining} ч</span></div></div><div class="task-buttons">${t.type==='chat'?action('Чат · '+name(t.peerId),'task-chat',t.id):t.type==='document'?action('Выбрать документ','task-doc',t.id):action('Открыть','task',t.id)}</div></div>`).join('')}
function tasks(){let ts=vt().filter(t=>(!taskProject||t.projectId===taskProject)&&(!taskStatus||t.status===taskStatus));const seller=!vp().length&&(u().role==='sales'||u().role==='sales_intern');return heading('Задачи',seller?'Чтобы не забыть клиенту, откройте карточку и нажмите «Следующий контакт». Задачи проектов появятся после передачи сделки.':'Единый список: изменения сразу видны в проекте',seller?'':action('+ Добавить задачу','new-task','',true))+`<div class="toolbar"><select id="task-project" aria-label="Проект задач">${option('','Все проекты',taskProject)+vp().map(p=>option(p.id,p.title,taskProject)).join('')}</select><select id="task-status" aria-label="Статус задач">${option('','Все статусы',taskStatus)+M.statuses.map(s=>option(s,s,taskStatus)).join('')}</select><span class="muted">${ts.length} задач</span></div><section class="panel">${taskRows(ts)}</section>`}
function taskForm(id='',fixedProject=''){const t=id?state.tasks.find(t=>t.id===id):null;if(t&&!M.canTask(state,u(),t))return toast('Задача недоступна');let pid=t?.projectId||fixedProject||taskProject||vp()[0]?.id;if(!pid)return toast((u().role==='sales'||u().role==='sales_intern')?'Задачи появляются в проектах. Чтобы не забыть клиенту, откройте карточку и нажмите «Следующий контакт».':'Нет доступных проектов для создания задачи');const manage=t?M.canManage(state,u(),pid):true;
 modal(t?'Задача проекта':'Новая задача',`<div class="form-grid">${t?`<div class="field">Проект<strong>${esc(M.project(state,pid).title)}</strong><input name="projectId" type="hidden" value="${pid}"></div>`:selectField('Проект','projectId',vp().map(p=>option(p.id,p.title,pid)).join(''))}${field('Название задачи','title',t?.title||'','text',true)}${field('Начало','start',t?.start||M.today(),'date',true)}${field('Срок','due',t?.due||M.today(),'date',true)}${field('Оценка, часов','estimate',t?.estimate??8,'number',true)}${field('Осталось, часов','remaining',t?.remaining??8,'number',true)}${selectField('Тип задачи','type',['work','chat','document'].map((k,i)=>option(k,['Работа','Обсуждение с участником','Отправить материал проекта'][i],t?.type||'work')).join(''))}<div id="assignment-slot"></div><div id="peer-slot"></div>${t?selectField('Статус','status',M.statuses.map(s=>option(s,s,t.status)).join('')):''}</div>${area('Описание','description',t?.description||'')}`,'Сохранить',fd=>{const input=Object.fromEntries(fd);input.estimate=+input.estimate;input.remaining=+input.remaining;if(t){if(!manage){M.updateTask(state,u(),id,{status:input.status,remaining:input.remaining,...(M.canAssign(state,u(),pid)&&'assigneeId'in input?{assigneeId:input.assigneeId}:{})})}else{const {projectId:ignored,...patch}=input;M.updateTask(state,u(),id,patch)}}else{const project=M.project(state,input.projectId);if(input.assigneeId&&project&&!project.members.includes(input.assigneeId)&&input.assigneeId!=='admin'){if(!M.canManage(state,u(),project.id))throw Error('Сначала добавьте исполнителя в участники проекта');project.members.push(input.assigneeId)}M.addTask(state,u(),input)}toast('Задача сохранена в общем списке и проекте')},t?'task:'+t.id:'task:new');
 const fill=()=>{const form=$('#modal-form'),project= M.project(state,form.elements.projectId.value);const allowed=M.canAssign(state,u(),project.id);$('#assignment-slot').innerHTML=allowed?selectField('Исполнитель','assigneeId',option('','Не назначен',t?.assigneeId)+state.users.filter(x=>project.members.includes(x.id)||x.role==='developer'||x.role==='admin').map(x=>option(x.id,x.name+' · '+M.roles[x.role],t?.assigneeId)).join('')):`<p class="hint">Исполнитель: ${esc(name(t?.assigneeId))}. Назначение исполнителей отключено в ваших правах.</p>`;$('#peer-slot').innerHTML=selectField('Участник для обсуждения','peerId',option('','Не выбран',t?.peerId)+state.users.filter(x=>project.members.includes(x.id)&&x.id!==u().id).map(x=>option(x.id,x.name,t?.peerId)).join(''));if(t&&!manage)for(const key of ['title','start','due','estimate','type','peerId','description'])form.elements[key].disabled=true;bindModalDraft($('#modal-form'))};fill();if(!t)$('#modal-form').elements.projectId.onchange=fill;
}
function roadmap(){return heading('Дорожные карты','Выберите проект, чтобы открыть именно его временную шкалу')+`<div class="project-grid">${vp().map(p=>`<button class="project-card" data-action="road" data-id="${p.id}"><div class="road-preview"><i></i><i></i><i></i></div><div class="project-body"><h3>${esc(p.title)}</h3><p>${fmt(p.start)} — ${fmt(p.due)}</p><span class="chip">Открыть дорожную карту →</span></div></button>`).join('')}</div>`}
function roadView(){let p=P();if(!p||!M.canProject(state,u(),p.id))return empty('Нет доступа');const ts=vt().filter(t=>t.projectId===p.id),dates=[p.start,p.due,...ts.flatMap(t=>[t.start,t.due])].filter(Boolean).sort();const from=Date.parse(dates[0]),to=Date.parse(dates.at(-1)),span=Math.max(86400000,to-from);const pos=d=>Math.max(0,Math.min(100,(Date.parse(d)-from)/span*100));return heading('Дорожная карта · '+p.title,!M.has(state,u(),'tasks.all')?'Ваши задачи и сроки в проекте':'Задачи проекта на временной шкале',action('← Все дорожные карты','go-roadmap')+action('Перейти в проект','project',p.id))+sheetsPanel()+`<div class="panel roadmap"><div class="panel-head"><span>${fmt(dates[0])}</span><strong>${esc(p.title)}</strong><span>${fmt(dates.at(-1))}</span></div><div class="road-axis"><span>Задача · исполнитель · срок</span><div>${Array.from({length:6},(_,i)=>`<span>${fmt(new Date(from+span*i/5).toISOString().slice(0,10))}</span>`).join('')}</div>${ts.map(t=>`<div class="road-row"><button class="road-task" data-action="task" data-id="${t.id}"><strong>${esc(t.title)}</strong><small>${esc(name(t.assigneeId))} · ${fmt(t.due)}</small></button><div class="track"><button class="road-bar ${t.status==='Готово'?'complete':''}" data-action="task" data-id="${t.id}" style="left:${Math.min(96,pos(t.start))}%;width:${Math.max(4,Math.min(100-pos(t.start),pos(t.due)-pos(t.start)))}%" title="${esc(t.title)}: ${fmt(t.start)} — ${fmt(t.due)}">${t.status}</button></div></div>`).join('')||empty('Пока нет назначенных задач')}</div><p class="hint">Сроки изменяются в карточке задачи. Строки относятся к той же задаче, что в проекте и общем списке.</p>`}
function aboutView(){const p=P();return `<div class="project-detail-grid"><section class="panel"><div class="panel-head"><h2>Коротко о проекте</h2>${M.canManage(state,u(),p.id)?link('Изменить','edit-project',p.id):''}</div><div class="detail">${typeof handoverBrief==='function'?handoverBrief(p):''}<p>${esc(p.description)}</p><div class="detail-grid"><div><small>Руководитель проекта</small>${esc(name(p.leaderId))}</div><div><small>Проджект-менеджер</small>${esc(name(p.pmId))}</div><div><small>Сроки</small>${fmt(p.start)} — ${fmt(p.due)}</div>${M.has(state,u(),'finance.view')?`<div><small>Бюджет проекта</small>${money(p.budget)}</div>`:''}</div><h3>Участники</h3>${p.members.map(id=>`<p>${esc(name(id))} · ${M.roles[state.users.find(x=>x.id===id)?.role]}</p>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Адресаты проекта</h2>${action('+ Адресат','add-recipient')}</div>${p.recipients.map(r=>`<div class="document"><div>${esc(r.name)}<small style="display:block">${esc(r.email)}</small></div></div>`).join('')||empty('Добавьте почту для коммуникаций')}</section></div>`}
function materialsView(){const docs=state.materials.filter(d=>d.projectId===projectId);return `${docTask?`<div class="hint">Задача: ${esc(state.tasks.find(t=>t.id===docTask)?.title)}. Выберите материал, затем нажмите «Отправить».</div>`:''}<div class="panel"><div class="panel-head"><h2>Материалы проекта</h2><div class="actions">${action('+ Загрузить файл','upload-material')}${action('Отправить','send-material','',true)}</div></div>${docs.map(d=>`<div class="document material-row"><label><input type="radio" name="document" value="${d.id}" ${chosenDoc===d.id?'checked':''}> <span>${esc(d.name)}<small>${fmt(d.createdAt)} · ${esc(name(d.createdBy))}</small></span></label>${link('Скачать','download-material',d.id)}</div>`).join('')||empty('Загрузите первый материал проекта')}</div><div class="panel" style="margin-top:20px"><div class="panel-head"><h2>Подготовленные письма</h2></div>${state.outbox.filter(o=>o.projectId===projectId).map(o=>`<div class="document"><div>${esc(o.to)}<small style="display:block">${esc(o.documentName)} · ${esc(o.status)}</small></div>${link('Скачать письмо','download-email',o.id)}</div>`).join('')||empty('Письма ещё не подготовлены')}</div><p class="hint">${mailStatus.configured?'Письмо с вложением уходит на почту адресата. Копию можно скачать.':'Почта не подключена — обратитесь к администратору. Письмо останется черновиком, его можно скачать.'}</p>`}
function legacyBoardView(){const p=P(),board=p.board,boardHeight=Math.max(850,...(board.assets||[]).map(a=>a.y+(a.image?480/a.ratio:100)+130));return `<div class="board-toolbar">${action('Загрузить скриншот / файл','board-upload','',true)}${action('+ Стикер','add-note','',true)}${action('Связать стикеры','add-link')}<label>Масштаб <select id="board-zoom">${[.5,.75,1,1.25].map(z=>option(z,z*100+'%',zoom)).join('')}</select></label><span class="muted">Перетаскивайте стикеры за верхнюю полоску</span></div><div class="board-scroll"><div style="width:${1600*zoom}px;height:${boardHeight*zoom}px"><div class="board-world" style="transform:scale(${zoom});height:${boardHeight}px"><svg class="connections" viewBox="0 0 1600 850">${board.links.map(l=>{let a=board.notes.find(n=>n.id===l.from),b=board.notes.find(n=>n.id===l.to);return a&&b?`<line x1="${a.x+100}" y1="${a.y+70}" x2="${b.x+100}" y2="${b.y+70}" stroke="#7c9aaa" stroke-width="2"/>`:''}).join('')}</svg>${boardAssetCards()}${board.notes.map(n=>`<article class="sticky ${n.color}" style="left:${n.x}px;top:${n.y}px" data-note="${n.id}"><div class="sticky-handle" data-drag-note="${n.id}"><span>${esc(name(n.author))}</span>${link('Изменить','edit-note',n.id)}</div><p>${esc(n.text)}</p></article>`).join('')}</div></div></div><p class="hint">Доска и обсуждения сохраняются в этом браузере. Одновременная работа нескольких пользователей требует серверного подключения.</p>`}
function discussionView(){const msgs=state.messages.filter(m=>m.projectId===projectId);return `<section class="panel"><div class="panel-head"><h2>Обсуждения проекта</h2>${action('Начать обсуждение','project-chat','',true)}</div><p class="report-note">Сообщения из чатов задач хранятся здесь и доступны участникам проекта.</p>${msgs.map(m=>`<div class="discussion-row"><div><strong>${esc(name(m.from))} → ${esc(m.to?name(m.to):'команде проекта')}</strong><small>${esc(state.tasks.find(t=>t.id===m.taskId)?.title||'Общее обсуждение')} · ${new Date(m.at).toLocaleString('ru-RU')}</small><p>${esc(m.text)}</p></div>${link('Открыть чат','message-chat',m.id)}</div>`).join('')||empty('Обсуждений пока нет')}</section>`}
function startChat(pid,peerId,taskId=''){if(!M.canProject(state,u(),pid))throw Error('Проект недоступен');if(!M.project(state,pid).members.includes(peerId)&&peerId!=='admin')throw Error('Участник недоступен');chat={projectId:pid,peerId,taskId};renderChat();hydrateBoardImages()}
function renderChat(){if(!chat||!M.canProject(state,u(),chat.projectId)){$('#chat-root').innerHTML='';return}const msgs=state.messages.filter(m=>m.projectId===chat.projectId&&m.taskId===chat.taskId);$('#chat-root').innerHTML=`<section class="chat-widget" aria-label="Чат проекта"><div class="chat-head"><div><strong>${esc(name(chat.peerId))}</strong><small>${esc(M.project(state,chat.projectId).title)}</small></div><button class="icon" data-action="close-chat" aria-label="Закрыть чат">×</button></div><p class="chat-context">${esc(state.tasks.find(t=>t.id===chat.taskId)?.title||'Обсуждение проекта')}<br>Видно участникам проекта</p><div class="chat-messages">${msgs.map(m=>`<div class="chat-bubble ${m.from===u().id?'mine':''}"><small>${esc(name(m.from))} → ${esc(name(m.to))}</small><p>${esc(m.text)}</p><small>${new Date(m.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<p class="muted">Начните обсуждение задачи.</p>'}</div><form id="chat-form"><textarea name="message" aria-label="Сообщение участнику" required maxlength="4000" placeholder="Напишите сообщение…"></textarea><button class="btn primary">Отправить</button></form></section>`;const list=$('.chat-messages');list.scrollTop=list.scrollHeight}
function reports(){const r=M.report(state,u(),{project:reportProject,from:reportFrom,to:reportTo}),scope={admin:'Полный обзор: продажи, проекты, финансы, задачи и сроки',leader:'Только проекты, где вы назначены руководителем',sales:'Только ваши клиенты, лиды, сделки и назначенные задачи',sales_intern:'Свои лиды, клиенты и задачи стажёра',rop:'Все лиды и продажи отдела: воронки, конверсия и менеджеры',pm:'Проекты, в которых вы участвуете: задачи и сроки',developer:'Только ваша часть разработки в проектах, где вы участвуете'}[u().role];let counts=[['В работе',r.risk.working.length],['В очереди',r.risk.queued.length],['Просрочено',r.risk.overdue.length],['Критично',r.risk.critical.length],['Выполнено',r.risk.done.length]];return heading('Отчёты','По текущим правам: доступные клиенты, проекты и задачи')+`<div class="toolbar"><select id="report-project" aria-label="Проект отчёта">${option('','Все доступные проекты',reportProject)+vp().map(p=>option(p.id,p.title,reportProject)).join('')}</select>${r.sales?`<label>Сделки с <input id="report-from" type="date" value="${reportFrom}"></label><label>по <input id="report-to" type="date" value="${reportTo}"></label>`:''}</div><div class="metrics">${counts.map(([l,v])=>`<section class="stat"><div class="stat-label">${l}</div><strong>${v}</strong></section>`).join('')}</div><p class="footnote">Просрочено: срок раньше сегодняшнего дня и задача не завершена. Критично: до срока 0–3 дня, осталось ≥ 8 часов. Статусы задач показывают текущее состояние.</p><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Задачи по статусам</h2></div>${barChart(M.statuses.map(s=>[s,r.tasks.filter(t=>t.status===s).length]))}</section><section class="panel"><div class="panel-head"><h2>Сроки и готовность проектов</h2></div>${r.projects.map(p=>`<div class="report-project"><strong>${esc(p.title)}</strong><span>${fmt(p.due)} · ${M.progress(state,u(),p.id)}% ${!M.has(state,u(),'tasks.all')?'ваших задач':''}</span><div class="progress"><span style="width:${M.progress(state,u(),p.id)}%"></span></div>${link('Роад мэп →','road',p.id)}</div>`).join('')}</section></div>${r.sales?salesReport(r):''}${r.finance?`<section class="panel report-section"><div class="panel-head"><h2>Суммы сделок по проектам</h2></div>${dataTable(['Проект','Бюджет проекта','Сумма связанных сделок'],r.projects.map(p=>[p.title,money(p.budget),money(r.clients.filter(c=>c.project===p.id).reduce((a,c)=>a+c.amount,0))]))}<p class="report-note">Бюджеты и суммы сделок не равны поступившим платежам. Учёт реальных оплат в этот UX-прототип не подключён.</p></section>`:''}<section class="panel report-section"><div class="panel-head"><h2>Задачи с риском по срокам</h2></div>${taskRows([...new Map([...r.risk.overdue,...r.risk.critical].map(t=>[t.id,t])).values()])}</section>`}
function barChart(rows){const max=Math.max(1,...rows.map(r=>r[1]));return `<div class="bars-report">${rows.map(([l,v])=>`<div class="bar-report-row"><span>${esc(l)}</span><div><i style="width:${v/max*100}%"></i></div><strong>${v}</strong></div>`).join('')}</div>`}
function dataTable(headers,rows){return `<div class="table-wrap"><table class="compact-clients"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function salesReport(r){const group=key=>[...new Set(r.clients.map(c=>c[key]))].map(k=>{const cs=r.clients.filter(c=>c[key]===k),won=cs.filter(c=>M.stage(state,c)?.kind==='won').length;return [key==='ownerId'?name(k):k,cs.length,won,(cs.length?won/cs.length*100:0).toFixed(1)+'%',money(cs.reduce((a,c)=>a+c.amount,0))]});return `<div class="metrics report-section"><section class="stat"><span>Сделок</span><strong>${r.clients.length}</strong></section><section class="stat"><span>Успешных</span><strong>${r.won.length}</strong></section><section class="stat"><span>Конверсия</span><strong>${r.conversion.toFixed(1)}%</strong></section><section class="stat"><span>Сумма сделок</span><strong class="amount">${money(r.total)}</strong></section><section class="stat"><span>Успешные сделки</span><strong class="amount">${money(r.wonTotal)}</strong></section></div><p class="footnote">Конверсия = текущие успешные сделки / все сделки, созданные в выбранном периоде. Успешный этап задаётся в настройке воронки. Это не последовательная конверсия между этапами.</p><section class="panel report-section"><div class="panel-head"><h2>Отчёт по воронкам</h2></div>${state.pipelines.map(p=>`<div class="pipeline-report"><h3>${esc(p.name)}</h3>${barChart(p.stages.map(s=>[s.name,r.clients.filter(c=>c.pipelineId===p.id&&c.stageId===s.id).length]))}</div>`).join('')}</section><div class="report-grid report-section"><section class="panel"><div class="panel-head"><h2>${LeadModel.isSales(u())?'Мои результаты':'Аналитика по менеджерам'}</h2></div>${dataTable(['Менеджер','Сделки','Успех','Конверсия','Сумма'],group('ownerId'))}</section><section class="panel"><div class="panel-head"><h2>Аналитика по каналам</h2></div>${dataTable(['Канал','Сделки','Успех','Конверсия','Сумма'],group('source'))}</section></div>`}
function legacyTeam(){const descriptions={admin:'Полный обзор всех проектов, воронок, финансов и задач. Назначает исполнителей.',leader:'Руководит назначенными проектами. Назначает исполнителей только в своих проектах.',sales:'Свои клиенты и лиды, своя часть воронки, конверсия и собственные задачи.',sales_intern:'Своя база и аналитика. При распределении учитывается только категория стажёров.',rop:'Все клиенты отдела, импорт баз и распределение по категориям, воронки и аналитика продаж. Не назначает исполнителей задач проектов.',pm:'Планирование и организация проектов, в которых участвует. Не назначает исполнителей.',developer:'Собственные задачи и сроки, материалы и обсуждения проектов, в которых участвует.'};return heading('Команда и роли','Для проверки выберите пользователя в правом верхнем углу',u().role==='admin'?action('Добавить пользователя','add-user','',true):'')+`<div class="role-grid">${Object.entries(M.roles).map(([k,title])=>`<section class="panel"><div class="detail"><h2>${title}</h2><p>${descriptions[k]}</p><div>${state.users.filter(x=>x.role===k).map(x=>`<p>${esc(x.name)}${x.active===false?' · Не участвует в распределении':''} ${u().role==='admin'?link('Настроить','edit-user',x.id):''}</p>`).join('')}</div></div></section>`).join('')}</div><p class="hint">Переключатель — инструмент проверки UX. Он не является авторизацией. Защищённые права и доступ к данным между компьютерами реализуются на сервере перед использованием реальной базы.</p>`}
function allowedProject(){if(!P()||!M.canProject(state,u(),projectId))throw Error('Нет доступа к проекту');return P()}
function stageForm(id=''){if(!M.has(state,u(),'pipelines.manage'))throw Error('Настройка этапов недоступна');let pipe=state.pipelines.find(p=>p.id===pipeId),st=pipe.stages.find(s=>s.id===id);modal(st?'Изменить этап':'Новый этап воронки',field('Название этапа','name',st?.name||'','text',true)+selectField('Значение этапа для отчётов','kind',[['open','В работе'],['won','Успешная сделка'],['lost','Отказ']].map(([k,l])=>option(k,l,st?.kind||'open')).join('')),'Сохранить',fd=>{const title=fd.get('name').trim();if(!title)throw Error('Введите название');if(st){if(pipe.stages.some(s=>s.id!==st.id&&s.name.toLowerCase()===title.toLowerCase()))throw Error('Название уже занято');st.name=title;st.kind=fd.get('kind');for(const c of state.clients.filter(c=>c.stageId===st.id))c.stage=title}else M.addStage(state,u(),pipe.id,title,fd.get('kind'));toast('Этап сохранён. Количество этапов не ограничено.')})}
function clientForm(id=''){const c=id?state.clients.find(c=>c.id===id):null;if(c&&!M.canClient(state,u(),c))throw Error('Клиент недоступен');if(!c&&!M.has(state,u(),'clients.edit'))throw Error('Добавление клиентов недоступно');modal(c?'Изменить клиента':'Новый клиент',field('Имя','name',c?.name||'','text',true)+field('Компания','company',c?.company||'','text',false)+field('Телефон','phone',c?.phone||'','tel',false)+field('Почта','email',c?.email||'','email')+area('Соцсети и мессенджеры — полные ссылки, по одной на строку','socials',c?.socials||'')+field('Сумма сделки','amount',c?.amount||0,'number',true)+field('Источник / канал','source',c?.source||'Вручную','text',true)+field('Дата сделки','dealDate',c?(c.dealDate||''):M.today(),'date')+area('Описание клиента','description',c?.description||'')+area('Задача клиента','clientTask',c?.clientTask||'')+area('Варианты КП: суммы и сроки','kpVariants',c?.kpVariants||'')+field('Ссылка на интерактивное КП','kpLink',c?.kpLink||'','url')+field('Дата и время созвона','callAt',(c?.callAt||'').slice(0,16),'datetime-local')+field('Заметка по статусу','statusNote',c?.statusNote||'')+selectField('Воронка','pipelineId',state.pipelines.map(p=>option(p.id,p.name,c?.pipelineId||pipeId)).join(''))+(LeadModel.canImport(u(),state)?selectField('Менеджер','ownerId',option('','Не назначен',c?.ownerId||'')+state.users.filter(x=>LeadModel.isSales(x)).map(x=>option(x.id,x.name,c?.ownerId||'')).join('')):'')+selectField('Связанный проект','project',option('','Не связан',c?.project)+vp().map(p=>option(p.id,p.title,c?.project)).join('')),'Сохранить',fd=>{let v=Object.fromEntries(fd);v.amount=+v.amount;if(!v.name.trim())throw Error('Заполните имя');const profiles=LeadModel.socialLinks(v);v.socials=profiles.join('\n');if(!v.phone.trim()&&!v.email.trim()&&!profiles.length)throw Error('Укажите телефон, email или профиль соцсети');if(state.clients.some(x=>x.id!==c?.id&&LeadModel.socialLinks(x).some(link=>profiles.includes(link))))throw Error('Этот профиль уже есть в базе');const normalized=v.phone.replace(/\D/g,'');if(v.phone&&(normalized.length<10||normalized.length>15))throw Error('Проверьте телефон');if(state.clients.some(x=>x.id!==c?.id&&normalized&&LeadModel.phone(x.phone)===LeadModel.phone(v.phone)))throw Error('Такой телефон уже есть в базе');if(c){let oldPipe=c.pipelineId,oldOwner=c.ownerId||'';if(c.project&&!M.canProject(state,u(),c.project))v.project=c.project;Object.assign(c,v);c.notes||=[];if((c.ownerId||'')!==oldOwner)c.notes.unshift('Ответственный: '+name(c.ownerId)+' · '+name(u().id)+' · '+M.today());if(oldPipe!==c.pipelineId){c.inLeadBase=false;c.stageId=state.pipelines.find(p=>p.id===c.pipelineId).stages[0].id;c.stageHistory.push({at:M.today(),stageId:c.stageId})}}else{const pipe=state.pipelines.find(p=>p.id===v.pipelineId),initial=LeadModel.manualStage(state,v.pipelineId);selected=M.uid();const ownerId=LeadModel.canImport(u(),state)?(v.ownerId||''):u().id;state.clients.push({...v,id:selected,ownerId,stageId:initial.id,stageHistory:[{at:M.today(),stageId:initial.id}],createdAt:M.today(),notes:ownerId?['Ответственный: '+name(ownerId)+' · '+M.today()]:[],next:'Назначить первый контакт',when:''})}page='clients';search='';toast('Клиент сохранён')},c?'client:'+c.id:'client:new')}
function teamGap(text){return text?`<p class="hint team-gap">${esc(text)} <button type="button" class="link" data-action="open-team">Перейти в «Команда и роли»</button></p>`:''}
function peopleSelect(label,key,people,selected,kind){const current=people.some(person=>person.id===selected)?selected:'';return `<label class="field">${label}<select name="${key}">${option('','— не выбран —',current)+people.map(person=>option(person.id,M.userLabel(person),current)).join('')}</select>${teamGap(M.projectTeamHint(people,kind))}</label>`}
function staffAdder(){if(u().role!=='admin')return '';return `<fieldset class="inline-staff"><legend>+ Сотрудник</legend><p class="hint">Человек сохранится на сервере и сразу появится в списках. Пароль в черновик не записывается.</p><div class="form-grid">${field('Имя','staffName')}${field('Логин','staffLogin')}${field('Временный пароль','staffPassword','','password')}${selectField('Роль','staffRole',Object.entries(M.roles).map(([k,v])=>option(k,v,'developer')).join(''))}</div><button type="button" class="btn" data-action="add-project-member">Добавить в проект</button><p class="form-error" id="staff-error" hidden></p></fieldset>`}
function memberChoices(project){const people=M.projectMemberChoices(state.users);const list=people.length?people.map(person=>`<label class="member-choice"><input type="checkbox" name="members" value="${esc(person.id)}" ${(project?.members||[]).includes(person.id)?'checked':''}> ${esc(M.userLabel(person))}</label>`).join(''):teamGap(M.projectTeamHint(people,'members'));return `<fieldset><legend>Участники проекта</legend>${list}${staffAdder()}</fieldset>`}
function projectForm(id=''){let p=M.project(state,id);if(p?!M.canManage(state,u(),p.id):!M.has(state,u(),'projects.create'))throw Error('Недостаточно прав');const leaders=M.projectLeaderChoices(state.users),managers=M.projectManagerChoices(state.users),canEditTeam=M.canManage(state,u(),p?.id)||!p;const draftId=projectDraftId(p?.id||'');modal(p?'Настройки проекта':'Новый проект',field('Название','title',p?.title||'','text',true)+field('Заказчик','client',p?.client||'','text',true)+area('Коротко о проекте','description',p?.description||'')+field('Начало','start',p?.start||M.today(),'date',true)+field('Срок','due',p?.due||'','date',false)+(M.has(state,u(),'finance.view')?field('Бюджет','budget',p?.budget||0,'number',true):'')+peopleSelect('Руководитель проекта','leaderId',leaders,p?.leaderId,'leader')+peopleSelect('Проджект-менеджер','pmId',managers,p?.pmId,'pm')+(canEditTeam?memberChoices(p):staffAdder()),'Сохранить',fd=>{const v=Object.fromEntries(fd);for(const key of ['staffName','staffLogin','staffPassword','staffRole'])delete v[key];if(v.start>v.due)throw Error('Начало позже срока');const picked=canEditTeam?[...fd.getAll('members')]:(p?.members||[]);const team=M.normalizeProjectTeam(state.users,u(),{leaderId:v.leaderId||'',pmId:v.pmId||'',members:picked},p||null);if(p){const removed=(p.members||[]).filter(member=>!team.members.includes(member));if(state.tasks.some(t=>t.projectId===p.id&&removed.includes(t.assigneeId)&&t.status!=='Готово'))throw Error('Сначала переназначьте активные задачи исключаемого участника');Object.assign(p,v,{members:team.members,leaderId:team.leaderId,pmId:team.pmId,budget:'budget'in v?+v.budget:p.budget})}else{p={...v,id:M.uid(),members:team.members,leaderId:team.leaderId,pmId:team.pmId,budget:'budget'in v?+v.budget:0,type:'crm',status:'Проектирование',next:'Согласовать план',recipients:[],board:{notes:[],links:[],comments:[]},mockup:{name:'',data:''}};state.projects.push(p)}projectId=p.id;projectTab='about';page='project';toast('Проект сохранён')},draftId)}
function noteForm(id=''){const p=allowedProject(),n=p.board.notes.find(n=>n.id===id);modal(n?'Изменить стикер':'Новый стикер',area('Текст','text',n?.text||'')+selectField('Цвет','color',['yellow','blue','pink','green'].map((k,i)=>option(k,['Жёлтый','Голубой','Розовый','Зелёный'][i],n?.color||'yellow')).join(''))+`<div class="form-grid">${field('Позиция X','x',n?.x??100,'number')}${field('Позиция Y','y',n?.y??100,'number')}</div>`,'Сохранить',fd=>{if(!fd.get('text').trim())throw Error('Введите текст');const v={text:fd.get('text').trim(),color:fd.get('color'),x:Math.max(0,Math.min(1380,+fd.get('x'))),y:Math.max(0,Math.min(650,+fd.get('y')))};if(n)Object.assign(n,v);else p.board.notes.push({...v,id:M.uid(),author:u().id});toast('Стикер сохранён')})}
function upload(kind){const p=allowedProject();modal(kind==='mockup'?'Загрузить макет':'Добавить материал',`<label class="field">Файл<input type="file" id="project-file" required accept="${kind==='mockup'?'.png,.jpg,.jpeg,.webp':'.pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg,.webp'}"></label><p class="hint">До 2 МБ на файл. Файл сохранится на сервере и будет доступен участникам проекта.</p>`,'Сохранить',async()=>{const file=$('#project-file').files[0];if(!file)throw Error('Выберите файл');if(file.size>2*1024*1024)throw Error('Файл превышает 2 МБ');const ext=file.name.split('.').pop().toLowerCase(),allowed=kind==='mockup'?['png','jpg','jpeg','webp']:['pdf','docx','xlsx','csv','txt','png','jpg','jpeg','webp'];if(!allowed.includes(ext))throw Error('Этот формат не поддерживается');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Не удалось прочитать файл'));r.readAsDataURL(file)});if(kind==='mockup')p.mockup={name:file.name,data};else state.materials.push({id:M.uid(),projectId:p.id,name:file.name,mime:file.type||'application/octet-stream',data,createdBy:u().id,createdAt:M.today()});toast('Файл будет сохранён на сервере')})}
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function materialBlob(d){if(d.text)return new Blob([d.text],{type:d.mime});const base=d.data.split(',')[1],bytes=Uint8Array.from(atob(base),c=>c.charCodeAt(0));return new Blob([bytes],{type:d.mime})}
function bytes64(s){return btoa(String.fromCharCode(...new TextEncoder().encode(s)))}
function makeEmail(o){const d=state.materials.find(d=>d.id===o.documentId);if(!d)throw Error('Материал не найден');const boundary='CRM-'+o.id;const base=d.data?d.data.split(',')[1]:bytes64(d.text);const fileName=d.name.replace(/[\r\n"\\]/g,'_');return ['MIME-Version: 1.0','To: '+o.to,'Subject: =?UTF-8?B?'+bytes64(o.subject)+'?=','Content-Type: multipart/mixed; boundary="'+boundary+'"','','--'+boundary,'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','',bytes64(o.body),'--'+boundary,'Content-Type: '+d.mime,'Content-Disposition: attachment; filename="attachment"; filename*=UTF-8\'\''+encodeURIComponent(fileName),'Content-Transfer-Encoding: base64','',base.match(/.{1,76}/g).join('\r\n'),'--'+boundary+'--',''].join('\r\n')}
function sendMaterial(){const p=allowedProject(),d=state.materials.find(x=>x.id===chosenDoc&&x.projectId===p.id);if(!d)throw Error('Выберите документ из материалов проекта');modal('Отправить материал',`<p><strong>${esc(d.name)}</strong></p>`+selectField('Адресат проекта','recipient',option('','Введите почту ниже','')+p.recipients.map(r=>option(r.email,r.name+' · '+r.email,'')).join(''))+field('Или введите почту','email','','email')+field('Тема','subject','Материалы проекта «'+p.title+'»','text',true)+area('Сообщение','body','Здравствуйте! Направляем материал проекта во вложении.')+`<p class="mail-confirm"><strong>Кому:</strong> адресат ниже, <strong>канал:</strong> почта</p>`+(mailStatus.configured?'':'<p class="hint">Почта не подключена — обратитесь к администратору. Письмо останется черновиком, его можно скачать.</p>'),mailStatus.configured?'Отправить':'Сохранить черновик',async fd=>{const to=(fd.get('email')||fd.get('recipient')).trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to))throw Error('Введите корректную почту');const client=(state.clients||[]).find(item=>item.project===p.id&&M.canClient(state,u(),item)&&String(item.email||'').toLowerCase()===to.toLowerCase())||(state.clients||[]).find(item=>item.project===p.id&&M.canClient(state,u(),item));if(!client)throw Error('Это не ваш клиент');if(mailStatus.configured&&!window.confirm('Кому: '+to+', канал: почта?'))return false;await mailApi('/api/mail/send',{clientId:client.id,to,confirmTo:to,subject:fd.get('subject'),text:fd.get('body'),materialId:d.id});toast(mailStatus.configured?'Письмо отправлено':'Почта не подключена — обратитесь к администратору');return 'saved'})}
function taskChat(id){const t=vt().find(t=>t.id===id);if(!t||t.type!=='chat')throw Error('Обсуждение недоступно');startChat(t.projectId,t.peerId===u().id?t.assigneeId||t.createdBy:t.peerId,t.id)}
async function act(a,id=''){
 if(a==='open-duplicate-client'){const dialog=$('#modal');if(dialog?.open)dialog.close();selected=id;return go('clients')}
 if(a==='logout')return logout();
 if(a==='change-password')return changePassword();
 if(a==='migration-export')return exportServerJson();
 if(a==='migration-local')return importLocalPrototype();
 if(a==='migration-pick')return $('#migration-file').click();
 if(a.startsWith('inbox-'))return inboxAction(a,id);
 accessAction(a);if(a==='access-create'||a==='add-user')return createEmployee();if(a==='access-user'||a==='edit-user')return permissionCard(id);if(a==='access-role')return rolePermissionsForm(id);
 if(a.startsWith('wb-'))return wbAction(a,id);
 if(a.startsWith('board-'))return boardAction(a,id);if(a.startsWith('sheets-'))return sheetsAction(a);
 if(a==='comm-call'||a==='comm-meeting')return communicationForm(a==='comm-call'?'call':'meeting',id);
 if(a==='voice-campaign')return voiceForm();
 if(a==='voice-cancel'){Communications.cancelCampaign(state,u(),id);persist();return voiceForm()}

 if(['load-funnel-batch','promote-leads','restore-batch','archive-batch','lead-category','group-existing','choose-lead-batch','import-leads','batch','distribute-leads','add-user','edit-user','batches','batch-prev','batch-next'].includes(a))return leadAction(a,id);
 if(a==='close-modal'){saveModalDraft($('#modal-form'));return $('#modal').close()}if(a==='close-chat'){chat=null;return renderChat();hydrateBoardImages()}
 if(a==='clear-draft'){const form=$('#modal-form');const draftId=form?.dataset.draftId||'';if(form)form.dataset.draftDone='1';CRMDraft.forgetDraft(draftStore(),u().id,draftId);if(draftId.startsWith('project:')){clearProjectReturn();return projectForm(draftId==='project:new'?'':draftId.slice(8))}if(draftId.startsWith('client:'))return clientForm(draftId==='client:new'?'':draftId.slice(7));if(draftId.startsWith('task:'))return taskForm(draftId==='task:new'?'':draftId.slice(5));return}
 if(a==='return-project-form')return projectForm(projectReturnId()||'');
 if(a==='add-project-member'){const form=$('#modal-form');try{saveModalDraft(form);const employee=saveNewEmployee({name:form.elements.staffName.value,login:form.elements.staffLogin.value,password:form.elements.staffPassword.value,role:form.elements.staffRole.value});const draftId=form.dataset.draftId;const current=CRMDraft.readDraft(draftStore(),u().id,draftId);const members=[...new Set([...(current?.values.members||[]),employee.id])];CRMDraft.rememberDraft(draftStore(),u().id,draftId,{...(current?.values||readDraftForm(form)),members});const scroll=$('#modal')?.scrollTop||0;projectForm(draftId==='project:new'?'':String(draftId||'').slice(8));if($('#modal'))$('#modal').scrollTop=scroll;toast(employee.name+' добавлен и отмечен в участниках')}catch(err){const box=$('#staff-error');if(box){box.hidden=false;box.textContent=err.message}throw err}return}
 if(a==='open-team'){const form=$('#modal-form');saveModalDraft(form);if(form?.dataset.draftId?.startsWith('project:'))markProjectReturn(form.dataset.draftId);const d=$('#modal');if(d?.open)d.close();return go('team')}if(a.startsWith('go-'))return go(a.slice(3));if(a==='project')return openProject(id);if(a==='road')return openRoad(id);
 if(a==='project-tab'){allowedProject();projectTab=id;return render()}if(a==='client'){if(!vc().some(c=>c.id===id))throw Error('Клиент недоступен');selected=id;return go('clients')}
 if(a==='new-task')return taskForm('',id);if(a==='task')return taskForm(id);if(a==='new-client')return clientForm();if(a==='edit-client')return clientForm(id);if(a==='handover-lead')return handoverLead(id);if(a==='dev-task')return deliveryTaskForm(id);
 if(a==='mailing-send')return mailingSend(id);
 if(a==='mailing-list')return mailingList();
 if(a==='istok-keys')return istokKeys();
 if(a==='desk-settings')return deskSettings();
 if(a==='toggle-silence')return toggleSilence(id);
 if(a==='pitch-build')return pitchBuild(id);
 if(a==='pitch-send')return pitchSend(id);
 if(a==='pitch-suggest')return pitchSuggest(id);
 if(a==='pitch-template')return pitchTemplateForm();
 if(a==='pay-invoice')return payInvoice(id);
 if(a==='pay-mark')return payMark(id);
 if(a==='kp-build')return kpBuild(id);
 if(a==='kp-send')return kpSend(id);
 if(a==='kp-template')return kpTemplateForm();
 if(a==='kp-catalogue')return kpCatalogueForm();
 if(a==='kp-suggest')return kpSuggest(id);
 if(a==='ask-assign')return askAssign(id);
 if(a==='deal-discuss')return dealDiscuss(id);
 if(a==='deal-telegram')return dealTelegram(id);
 if(a==='phone'||a==='sipuni-call')return sipuniCall(id);
 if(a==='sipuni-open')return sipuniOpen(id);
 if(a==='sipuni-lead')return sipuniLead(id);
 if(a==='sipuni-test')return sipuniTest();
 if(a==='contact'){const c=vc().find(c=>c.id===id);if(!c)throw Error('Нет доступа');return modal('Следующий контакт',field('Что сделать','next',c.next,'text',true)+field('Когда','when',c.when?.slice(0,16)||'','datetime-local',true),'Сохранить',fd=>{c.next=fd.get('next');c.when=fd.get('when');c.notes.unshift('Следующий шаг: '+c.next);toast('Контакт запланирован')})}
 if(a==='add-stage'||a==='rename-stage')return stageForm(a==='rename-stage'?id:'');
 if(a==='add-pipeline'){if(!M.has(state,u(),'pipelines.manage'))throw Error('Нет доступа');return modal('Новая воронка',field('Название','name','','text',true),'Создать',fd=>{const name=fd.get('name').trim();if(!name)throw Error('Введите название');if(state.pipelines.some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('Воронка уже существует');pipeId=M.uid();state.pipelines.push({id:pipeId,name,stages:[{id:M.uid(),name:'Новый',kind:'open'},{id:M.uid(),name:'Отказ',kind:'lost'}]})})}
 if(a==='stage-left'||a==='stage-right'){if(!M.has(state,u(),'pipelines.manage'))throw Error('Нет доступа');const list=state.pipelines.find(p=>p.id===pipeId).stages,i=list.findIndex(s=>s.id===id),j=i+(a==='stage-left'?-1:1);if(j>=0&&j<list.length)[list[i],list[j]]=[list[j],list[i]];persist();return render()}
 if(a==='new-project'||a==='edit-project')return projectForm(id);
 if(a==='upload-material'||a==='upload-mockup')return upload(a==='upload-mockup'?'mockup':'material');
 if(a==='task-doc'){const t=vt().find(t=>t.id===id);if(!t)throw Error('Задача недоступна');projectId=t.projectId;projectTab='materials';chosenDoc='';docTask=id;return go('project')}
 if(a==='send-material')return sendMaterial();
 if(a==='mail-client')return mailClient(id);
 if(a==='mail-test')return mailTest();
 if(a==='download-material'){const d=state.materials.find(d=>d.id===id);if(!d||!M.canProject(state,u(),d.projectId))throw Error('Материал недоступен');return download(d.name,materialBlob(d))}
 if(a==='download-email'){const o=state.outbox.find(o=>o.id===id);if(!o||!M.canProject(state,u(),o.projectId))throw Error('Письмо недоступно');return download('Письмо-'+o.id.slice(0,8)+'.eml',new Blob([makeEmail(o)],{type:'message/rfc822'}))}
 if(a==='add-recipient'){const p=allowedProject();return modal('Адресат проекта',field('Имя / назначение','name','','text',true)+field('Почта','email','','email',true),'Сохранить',fd=>{const email=fd.get('email').trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Проверьте почту');if(p.recipients.some(r=>r.email.toLowerCase()===email.toLowerCase()))throw Error('Адресат уже добавлен');p.recipients.push({id:M.uid(),name:fd.get('name').trim(),email})})}
 if(a==='add-note'||a==='edit-note'){if(page==='project'&&projectTab==='board')return id?wbEdit(id):wbNewNote();return noteForm(id)}
 if(a==='add-link'){let p=allowedProject();if(p.board.notes.length<2)throw Error('Добавьте минимум два стикера');return modal('Связь между стикерами',selectField('От','from',p.board.notes.map(n=>option(n.id,n.text.slice(0,50),p.board.notes[0].id)).join(''))+selectField('К','to',p.board.notes.map(n=>option(n.id,n.text.slice(0,50),p.board.notes[1].id)).join('')),'Связать',fd=>{if(fd.get('from')===fd.get('to'))throw Error('Выберите разные стикеры');if(p.board.links.some(l=>l.from===fd.get('from')&&l.to===fd.get('to')))throw Error('Связь уже существует');p.board.links.push({id:M.uid(),from:fd.get('from'),to:fd.get('to')})})}
 if(a==='task-chat')return taskChat(id);
 if(a==='project-chat'){let p=allowedProject();return modal('Обсуждение проекта',selectField('С кем обсудить','peer',p.members.filter(x=>x!==u().id).map(x=>option(x,name(x),'')).join('')),'Открыть чат',fd=>{startChat(p.id,fd.get('peer'));return true})}
 if(a==='message-chat'){const m=state.messages.find(m=>m.id===id);if(!m||!M.canProject(state,u(),m.projectId))throw Error('Обсуждение недоступно');return startChat(m.projectId,m.from===u().id?m.to:m.from,m.taskId)}
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.funnelScroll){const board=$('#funnel-board');const step=(board?.querySelector('.stage-column')?.getBoundingClientRect().width||220)+14;board?.scrollBy({left:Number(b.dataset.funnelScroll)*step,behavior:'smooth'});return}if(b.dataset.go)go(b.dataset.go);else if(b.dataset.action)Promise.resolve(act(b.dataset.action,b.dataset.id||'')).catch(err=>toast(err.message))}catch(err){toast(err.message)}});
document.addEventListener('change',e=>{const v=e.target.value;try{if(e.target.id==='migration-file'){const file=e.target.files&&e.target.files[0];e.target.value='';if(!file)return;file.text().then(text=>importDump(JSON.parse(text))).catch(err=>toast(err.message));return}
else if(e.target.id==='pipeline'){pipeId=v;sessionStorage.setItem('crm-pipeline',v);render()}else if(e.target.id==='client-stage'){const moved=state.clients.find(c=>c.id===selected);e.target.value=moved.stageId;return moveToStage(moved,v)}else if(e.target.classList.contains('dev-stage')){DeliveryModel.moveProject(state,u(),e.target.dataset.id,v);if(!persist())return;render();toast('Проект переведён: '+DeliveryModel.stageById(v).name)}
else if(e.target.id==='task-project'){taskProject=v;render()}else if(e.target.id==='task-status'){taskStatus=v;render()}else if(e.target.id==='report-project'){reportProject=v;render()}else if(e.target.id==='report-from'){reportFrom=v;render()}else if(e.target.id==='report-to'){reportTo=v;render()}else if(e.target.name==='document')chosenDoc=v;else if(e.target.id==='board-zoom'){zoom=+v;render()}}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='client-search'){let n=e.target.selectionStart;search=e.target.value;render();$('#client-search').focus();$('#client-search').setSelectionRange(n,n)}});
async function changePassword(){modal('Сменить пароль',field('Текущий пароль','current','','password',true)+field('Новый пароль','password','','password',true)+field('Повторите новый пароль','again','','password',true)+'<p class="hint">Не короче 8 символов. Пароль никому не пересылайте.</p>','Сохранить',async fd=>{const next=String(fd.get('password')||'');if(next.length<8)throw Error('Новый пароль — не короче 8 символов');if(next!==fd.get('again'))throw Error('Новый пароль повторён неверно');const response=await fetch('/api/auth/password',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'ActivProfi'},body:JSON.stringify({currentPassword:fd.get('current')||'',password:next})});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Не удалось сменить пароль');if(state){const me=state.users.find(item=>item.id===u().id);if(me)me.mustChangePassword=false}toast('Пароль сохранён')})}
async function saveFirstPassword(fd){const next=String(fd.get('password')||''),error=$('#password-error');const fail=message=>{if(!error)return;error.hidden=false;error.textContent=message};if(next.length<8)return fail('Новый пароль — не короче 8 символов');if(next!==fd.get('again'))return fail('Новый пароль повторён неверно');const response=await fetch('/api/auth/password',{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'ActivProfi'},body:JSON.stringify({currentPassword:fd.get('current')||'',password:next})});const data=await response.json().catch(()=>({}));if(!response.ok)return fail(data.error||'Не удалось сменить пароль');await boot()}
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();login(new FormData(e.target)).catch(err=>showLogin(err.message));return}if(e.target.id==='password-form'){e.preventDefault();saveFirstPassword(new FormData(e.target)).catch(err=>{const error=$('#password-error');if(error){error.hidden=false;error.textContent=err.message}});return}if(e.target.id==='client-note'){e.preventDefault();const c=vc().find(c=>c.id===selected),note=new FormData(e.target).get('note').trim();if(c&&note&&M.has(state,u(),'clients.edit')){c.notes||=[];c.notes.unshift(name(u().id)+' · '+M.today()+': '+note);persist();render()}}if(e.target.id==='chat-form'){e.preventDefault();try{if(!chat||!M.canProject(state,u(),chat.projectId))throw Error('Нет доступа к чату');const text=new FormData(e.target).get('message').trim();if(!text)return;state.messages.push({id:M.uid(),projectId:chat.projectId,taskId:chat.taskId,from:u().id,to:chat.peerId,text,at:new Date().toISOString()});persist();if(page==='project'&&projectTab==='discussions')render();else renderChat();hydrateBoardImages()}catch(err){toast(err.message)}}});
let dragClient='';document.addEventListener('dragstart',e=>{let card=e.target.closest('[data-drag-client]');if(card){dragClient=card.dataset.dragClient;e.dataTransfer.setData('text/plain',dragClient);e.dataTransfer.effectAllowed='move'}});document.addEventListener('dragend',()=>{dragClient=''});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-stage]'))e.preventDefault()});document.addEventListener('drop',e=>{const col=e.target.closest('[data-drop-stage]');if(!col||!dragClient)return;e.preventDefault();try{const client=state.clients.find(c=>c.id===dragClient);moveToStage(client,col.dataset.dropStage)}catch(err){toast(err.message)}});
const LOSS_REASONS=[['price','Цена'],['timing','Сроки'],['other-vendor','Выбрал другого'],['no-need','Нет потребности'],['no-answer','Не отвечает'],['other','Другое']];
function lossReasonLabel(code){return LOSS_REASONS.find(item=>item[0]===code)?.[1]||''}
function lossForm(client,stageId){modal('Отказ',selectField('Причина','lossReason',LOSS_REASONS.map(([key,label])=>option(key,label,'price')).join(''))+field('Когда вернуться','returnAt','','date',true),'Сохранить отказ',fd=>{client.lossReason=fd.get('lossReason');client.returnAt=fd.get('returnAt');client.notes=client.notes||[];client.notes.unshift('Отказ: '+lossReasonLabel(client.lossReason)+' · вернуться '+client.returnAt);M.moveClient(state,u(),client.id,client.pipelineId,stageId);toast('Отказ записан')})}
function moveToStage(client,stageId){if(!client)return;if(!confirmStageBack(client,stageId))return;const stage=state.pipelines.find(p=>p.id===client.pipelineId)?.stages.find(item=>item.id===stageId);const current=M.stage(state,client);if(current?.kind!=='won'&&stage?.kind==='won')return handoverForm(client,stageId);if(stage?.kind==='lost'&&current?.kind!=='lost')return lossForm(client,stageId);M.moveClient(state,u(),client.id,client.pipelineId,stageId);if(!persist())return;render();toast('Клиент перемещён на этап')}
function confirmStageBack(client,stageId){const pipe=state.pipelines.find(p=>p.id===client?.pipelineId);if(!pipe)return true;const from=pipe.stages.findIndex(s=>s.id===client.stageId),to=pipe.stages.findIndex(s=>s.id===stageId);if(from<0||to<0||to>=from)return true;return window.confirm('Вернуть сделку на этап «'+pipe.stages[to].name+'»?')}
let noteDrag=null;document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag-note]');if(!h||e.target.closest('button'))return;const n=P()?.board.notes.find(n=>n.id===h.dataset.dragNote);if(!n||!M.canProject(state,u(),projectId))return;h.setPointerCapture(e.pointerId);noteDrag={id:n.id,x:n.x,y:n.y,cx:e.clientX,cy:e.clientY,el:h.closest('.sticky')};e.preventDefault()});document.addEventListener('pointermove',e=>{if(!noteDrag)return;const n=P().board.notes.find(n=>n.id===noteDrag.id);n.x=Math.max(0,Math.min(1380,noteDrag.x+(e.clientX-noteDrag.cx)/zoom));n.y=Math.max(0,Math.min(650,noteDrag.y+(e.clientY-noteDrag.cy)/zoom));noteDrag.el.style.left=n.x+'px';noteDrag.el.style.top=n.y+'px'});document.addEventListener('pointerup',()=>{if(noteDrag){noteDrag=null;const scroll=$('.board-scroll'),x=scroll?.scrollLeft||0,y=scroll?.scrollTop||0;persist();render();if($('.board-scroll')){$('.board-scroll').scrollLeft=x;$('.board-scroll').scrollTop=y}}});
$('#modal').addEventListener('close',()=>saveModalDraft($('#modal-form')));
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.name?.startsWith('staff'))e.preventDefault()});
boot();

